-- Mensaje 93 · Las reglas de los bloqueos se escriben como prueba, igual que el pitch prematuro (Emilio, 16-oct-2026).
-- Antes de tocar nada revisa que las citas estén en el Cerebro vigente y que cada guion esté en la versión esperada. El chequeo final aborta si algo no quedó.
DO $pre$ BEGIN
  IF NOT EXISTS (SELECT 1 FROM public.doctrina WHERE is_active AND strpos(body, $v$No hubo procesamiento. Es la puerta cerrándose sola.$v$) > 0) THEN RAISE EXCEPTION 'el Cerebro vigente no tiene la cita de blocks.se_rinde_al_bloqueo'; END IF;
  IF NOT EXISTS (SELECT 1 FROM public.doctrina WHERE is_active AND strpos(body, $v$no lo discutas, y continúa$v$) > 0) THEN RAISE EXCEPTION 'el Cerebro vigente no tiene la cita de blocks.air_sin_aceptar'; END IF;
  IF NOT EXISTS (SELECT 1 FROM public.doctrina WHERE is_active AND strpos(body, $v$Disculparte baja tu valor$v$) > 0) THEN RAISE EXCEPTION 'el Cerebro vigente no tiene la cita de opening.se_disculpa'; END IF;
END $pre$;

-- 1. Reglas nuevas.
INSERT INTO public.reglas (id, paso, tipo, canal, procedencia, resumen, cita_cerebro, severidad_default) VALUES ('blocks.se_rinde_al_bloqueo', 2, 'error', 'universal', 'CAMPO', $v$Rendirse ante un no por costumbre: tratar el reflejo del cliente como si fuera un no de verdad. LA PRUEBA: ante el PRIMER bloqueo, ¿el vendedor se va, se disculpa o promete volver antes de intentar AIR? Si acepta el no y sigue con su tema, no se rindió. Después de dos no seguidos, quedar de regresar o despedirse es lo correcto y no es esto.$v$, $v$No hubo procesamiento. Es la puerta cerrándose sola.$v$, 'critical') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.reglas (id, paso, tipo, canal, procedencia, resumen, cita_cerebro, severidad_default) VALUES ('blocks.air_sin_aceptar', 0, 'error', 'universal', 'FUENTE', $v$Seguir de largo sin reconocer lo que el cliente dijo: se siente que no lo escuchó. LA PRUEBA: ¿el vendedor sigue con su tema sin ninguna palabra que reconozca lo que el cliente acaba de decir («entiendo», «claro», «por supuesto», o algo que muestre que lo escuchó)? Si lo reconoce, aunque sea breve, no es esto.$v$, $v$no lo discutas, y continúa$v$, 'major') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.reglas (id, paso, tipo, canal, procedencia, resumen, cita_cerebro, severidad_default) VALUES ('opening.se_disculpa', 1, 'error', 'universal', 'FUENTE', $v$Disculparse o hacerse menos: comunica que sabe que estorba, y baja su valor. LA PRUEBA: ¿la frase pide perdón por estar ahí, por hablar o por el tiempo del cliente, o hace chica su presencia? Ejemplos que ilustran —no delimitan—: «perdón que lo moleste», «disculpe la molestia», «solo será un segundo», «no le quito mucho tiempo».$v$, $v$Disculparte baja tu valor$v$, 'critical') ON CONFLICT (id) DO NOTHING;

-- 2. Las reglas que ya existían, ahora con su prueba.
UPDATE public.reglas SET resumen = $v$Pedir autorización para hablar o para seguir: entrega el control y le ofrece al cliente una salida gratis. LA PRUEBA: ¿la frase le da al cliente la opción de decir que no a seguir la plática? Ejemplos que ilustran —no delimitan—: «¿tiene un minutito?», «¿me permite?», «¿le puedo preguntar algo?», «si no le molesta…». Si la frase no le da esa opción, no es pedir permiso, diga lo que diga.$v$, updated_at = now() WHERE id = 'opening.pide_permiso';
UPDATE public.reglas SET resumen = $v$Discutir un bloqueo lo convierte en posición y le crea al cliente un no que no tenía. LA PRUEBA: ¿el vendedor trata de cambiar el no del cliente: convencerlo de que sí le interesa, de que sí tiene tiempo o de que será rápido? Si acepta el no y sigue con su tema, no es discutir, diga lo que diga.$v$, updated_at = now() WHERE id = 'blocks.discute_bloqueo';
UPDATE public.reglas SET resumen = $v$Aceptar el bloqueo pero no retomar. LA PRUEBA: después de aceptar, ¿el vendedor se queda callado esperando que el cliente le dé pie, o pide permiso para seguir (con la prueba de pedir permiso: una frase que le da al cliente la opción de decir que no a seguir)? Si sigue con su tema o con una pregunta, sí retomó.$v$, updated_at = now() WHERE id = 'blocks.air_sin_resume';
UPDATE public.reglas SET resumen = $v$Seguir insistiendo después de dos no seguidos en la puerta: ya no es seguridad, es terquedad. LA PRUEBA: después del segundo no seguido, ¿el vendedor sigue con su tema (otra pregunta, una explicación, un «nomás un minutito») en vez de quedar de regresar o despedirse? Solo cuenta lo que dice después del segundo no.$v$, updated_at = now() WHERE id = 'blocks.insistir_tras_dos_no';

-- 3. Guiones: cada falla ligada a la regla que la define, y fuera las frases sueltas del 91.
UPDATE public.nodes SET practice_script = $g${"notes": "v2.0.0 El espejo castiga la disculpa con la consecuencia real de campo: el cliente toma el control y despacha. No hay regano, hay consecuencia. v2.0.2 (oct-2026, Emilio): decir quién eres o de qué empresa vienes no es pitch prematuro. El Director puede cortar desde el primer turno: la introducción no obliga a un segundo turno.", "scope": {"skills_in_focus": ["opening.arranque_sin_disculpa", "mindset.regla_10_por_ciento", "opening.estructura_apertura"], "out_of_scope_behavior": "redirect"}, "limits": {"max_turns": 5, "max_duration_seconds": 180, "min_turns_before_evaluation": 1}, "phases": {"i_do": {"briefing": "Este cliente esta ocupado y me lo va a hacer sentir.\n\nFijate en lo que NO hago: no me disculpo, no pregunto si tiene tiempo, no digo solo sera un segundito. Reconozco que esta ocupado y sigo con la misma energia, como quien tiene derecho a estar ahi.", "first_message": "Buenos dias! Ya veo que lo agarre en plena carga.\n\nQue bueno, eso quiere decir que hay trabajo. Como ha estado el movimiento esta semana?"}, "you_do": {"prompt": "REGLA NUMERO CERO, POR ENCIMA DE TODO LO DEMAS: en esta conversacion NO EXISTE el tema de que vende este senor, que trae, a que viene, ni en que te puede servir. Jamas preguntas eso. Ni con esas palabras ni con ninguna otra. Prohibidas de forma absoluta las frases: que se le ofrece, que necesita, que anda buscando, a que viene, que trae, de que se trata, en que le puedo servir, y cualquier variante. Tu no sabes que es vendedor y no te interesa averiguarlo. Si el menciona por su cuenta un producto o una marca, contestas ah orale y sigues con lo tuyo sin preguntar nada. Si te quedas sin saber que decir, hablas de tu propio negocio o del dia, nunca de el.\n\nEres el encargado de un negocio y estas genuinamente ocupado: atendiendo, acomodando, con cosas en la mano. No eres grosero, pero tampoco tienes tiempo que regalar y lo demuestras. TU REGLA PRINCIPAL: reaccionas a la POSTURA del vendedor, no a sus palabras. Si se disculpa, pide permiso o se minimiza (perdon que lo moleste, tiene un minutito, solo sera un segundo, disculpe la molestia), tomas el control de inmediato y lo despachas con naturalidad: ahorita ando ocupado, venga en otro momento. No es maldad, es que te dio la salida y la tomaste. Si entra con postura, reconoce que estas ocupado sin pedir permiso y mantiene su energia, le contestas de igual a igual aunque sigas trabajando: le das una respuesta breve pero real, sin despacharlo. Puedes estar distraido, contestar corto o seguir con lo tuyo mientras hablas. NUNCA preguntes que vende. Responde en 1 o 2 frases.", "objective": "El vendedor sostiene una apertura completa frente a un cliente ocupado, sin disculparse, sin pedir permiso y sin encogerse. El scope se cubre cuando el cliente, a pesar de estar ocupado, le contesta de igual a igual con una respuesta real en lugar de despacharlo."}, "closing": {"message": "Eso es entrar sin disculpa. Reconociste que estaba ocupado sin convertirlo en un permiso que pedir. La diferencia entre estorbar y pertenecer no esta en las palabras: esta en la postura. Vamos al detalle.", "message_incomplete": "Ahi lo dejamos, ya vi con que postura entras. Vamos al desglose."}}, "version": "2.0.3", "i_do_type": "demo", "failure_criteria": [{"id": "pide_permiso", "regla_id": "opening.pide_permiso", "severity": "critical", "description": "Pide autorizacion para hablar o para seguir: tiene un minuto, puedo robarle un momento, me permite. Le entrega el control al cliente y la respuesta mas facil siempre es no."}, {"id": "se_disculpa", "regla_id": "opening.se_disculpa", "severity": "critical", "description": "Abre disculpandose o minimizando su presencia. Comunica que sabe que estorba, y el cliente lo trata en consecuencia."}, {"id": "se_encoge", "regla_id": "opening.energia_verbal", "severity": "major", "description": "Ante la primera senal de que el cliente esta ocupado, baja la energia, se acorta o empieza a despedirse. Se rindio antes de que lo corrieran.", "espejo_de": "mindset.regla_10_por_ciento"}, {"id": "pitch_prematuro", "regla_id": "opening.pitch_prematuro", "severity": "critical", "description": "Ofrece producto o promoción, o pregunta por su operación comercial (proveedor, precios, marcas, volúmenes, cada cuánto le surten). Decir tu nombre o de qué empresa vienes NO es pitch prematuro, y menos si el cliente te lo preguntó: eso es la historia breve y en este nodo no se califica."}], "success_criteria": [{"id": "opening.arranque_sin_disculpa", "weight": 0.45, "regla_id": "opening.gasman", "description": "Cero disculpas, cero peticiones de permiso, cero minimizarse. Nada de perdon que lo moleste, tiene un minutito, solo sera un segundo, disculpe la molestia, no le quito mucho tiempo. Reconocer que el cliente esta ocupado SI es correcto y suma, siempre que no se convierta en pedir autorizacion para seguir."}, {"id": "mindset.regla_10_por_ciento", "weight": 0.25, "regla_id": "opening.energia_verbal", "description": "Sostiene la energia y la postura aunque el cliente conteste corto, siga trabajando o no le de atencion completa. No baja el volumen ni se encoge ante la indiferencia."}, {"id": "opening.estructura_apertura", "weight": 0.3, "regla_id": "opening.estructura", "description": "Mantiene la estructura de apertura aprendida: saludo con energía, observación real y una pregunta que cierre el turno. La presión del cliente ocupado no debe desarmar la fórmula."}]}$g$::jsonb WHERE id = '1.4' AND practice_script->>'version' = '2.0.2';
UPDATE public.nodes SET practice_script = $g${"notes": "v2.0.0 BOSS del Mundo 1. Sin pista garantizada y sin ayudas (R9): el gimnasio garantiza la oportunidad, el examen no. La senal de exito es que el cliente pregunte quien es el vendedor, que es la puerta natural al Mundo 2. v2.0.2 (oct-2026, Emilio): decir quién eres o de qué empresa vienes no es pitch prematuro. El Director puede cortar desde el primer turno: la introducción no obliga a un segundo turno.", "scope": {"skills_in_focus": ["opening.estructura_apertura", "opening.personalizacion", "opening.ice_breaker", "opening.arranque_sin_disculpa", "mindset.regla_10_por_ciento", "opening.curiosidad_abierta"], "out_of_scope_behavior": "redirect"}, "limits": {"max_turns": 8, "max_duration_seconds": 240, "min_turns_before_evaluation": 1}, "phases": {"i_do": {"briefing": "Este es el examen del mundo. Todo lo que practicaste por separado, junto y con un cliente que no ayuda.\n\nNo hay pistas ni facilidades: si la apertura no esta completa, el cliente no se abre.", "first_message": "Buenos dias! Ya lo vi en friega desde que venia llegando.\n\nSe nota que aqui no se descansa, eh? Oiga, y como ha estado la semana por aca?"}, "you_do": {"prompt": "REGLA NUMERO CERO, POR ENCIMA DE TODO LO DEMAS: en esta conversacion NO EXISTE el tema de que vende este senor, que trae, a que viene, ni en que te puede servir. Jamas preguntas eso. Ni con esas palabras ni con ninguna otra. Prohibidas de forma absoluta las frases: que se le ofrece, que necesita, que anda buscando, a que viene, que trae, de que se trata, en que le puedo servir, y cualquier variante. Tu no sabes que es vendedor y no te interesa averiguarlo. Si el menciona por su cuenta un producto o una marca, contestas ah orale y sigues con lo tuyo sin preguntar nada. Si te quedas sin saber que decir, hablas de tu propio negocio o del dia, nunca de el.\n\nEres el encargado de un negocio, ocupado y de pocas palabras. No eres grosero: eres alguien que ya vio pasar a muchos vendedores y no regala tiempo. TU COMPORTAMIENTO POR DEFECTO es cortes y cerrado: contestas en tres o cuatro palabras, sin ofrecer nada, sin preguntar nada. SOLO TE ABRES SI SE GANAN: si el vendedor se disculpa, pide permiso o se minimiza, lo despachas de inmediato con un ahorita ando ocupado. Si su observacion es generica o plana, contestas con monosilabos y sigues en lo tuyo. Si te hace una pregunta cerrada, contestas no y se acabo. Si el vendedor logra las tres cosas — entra con postura sin pedir permiso, dice algo ligero y verdadero que te haga sonreir o contestar de vuelta, y cierra con una pregunta abierta — entonces si: bajas la guardia, contestas con gusto, comentas algo de tu negocio por tu cuenta y le preguntas quien es. Esa pregunta es la senal de que gano la apertura. NUNCA preguntes quien es antes de que se lo gane. NUNCA hables de productos. Responde en 1 o 2 frases.", "objective": "El vendedor ejecuta la apertura completa frente a un cliente que no facilita nada: entra con postura y sin pedir permiso, rompe el hielo con algo ligero y verdadero, y abre con una pregunta que le devuelve la palabra. El scope se cubre cuando el cliente baja la guardia por su propia voluntad y pregunta quien es el vendedor, que es la puerta natural al siguiente paso."}, "closing": {"message": "Ahi esta la primera impresion completa. Entraste con postura, rompiste el hielo con algo verdadero y abriste la conversacion sin pedirle permiso a nadie. Ese cliente ya quiere saber quien eres, y eso es exactamente lo que sigue. Vamos al detalle.", "message_incomplete": "Hasta aqui la sesion. Ya tengo lo que necesito para tu analisis. Vamos al desglose y te digo donde estuvo la diferencia."}}, "version": "2.0.3", "i_do_type": "demo", "failure_criteria": [{"id": "pide_permiso", "regla_id": "opening.pide_permiso", "severity": "critical", "description": "Pide autorizacion en cualquier momento de la sesion. En el boss este error domina el resultado: la primera impresion murio ahi."}, {"id": "se_disculpa", "regla_id": "opening.se_disculpa", "severity": "critical", "description": "Se disculpa o minimiza su presencia en cualquier momento."}, {"id": "pitch_prematuro", "regla_id": "opening.pitch_prematuro", "severity": "critical", "description": "Ofrece producto o promoción, o pregunta por su operación comercial (proveedor, precios, marcas, volúmenes, cada cuánto le surten). Decir tu nombre o de qué empresa vienes NO es pitch prematuro, y menos si el cliente te lo preguntó: eso es la historia breve y en este nodo no se califica."}, {"id": "pregunta_cerrada", "regla_id": "opening.pregunta_cerrada", "severity": "major", "description": "Cierra la apertura con una pregunta de si o no."}, {"id": "se_encoge", "regla_id": "opening.energia_verbal", "severity": "major", "description": "Ante la sequedad del cliente baja la energia o empieza a retirarse.", "espejo_de": "mindset.regla_10_por_ciento"}], "success_criteria": [{"id": "opening.estructura_apertura", "weight": 0.2, "regla_id": "opening.estructura", "description": "Las tres piezas presentes: saludo con energía, observación real y una pregunta que cierre el turno. Sin producto ni motivo de venta. Identificarse no se requiere aquí: eso es trabajo del Paso 2."}, {"id": "opening.personalizacion", "weight": 0.2, "regla_id": "opening.especificidad", "description": "La observacion es de ESE cliente y ESE momento, verificable en lo que el cliente dice o hace. Nada generico ni inventado."}, {"id": "opening.ice_breaker", "weight": 0.15, "regla_id": "opening.ice_breaker", "description": "Hay un cumplido genuino, un chiste sencillo o un comentario ligero —casual y amable, sin peso comercial— sobre la persona, el lugar o algo en común. Lo que no cumple es un comentario que suena a inspección: contarle la mercancía o describir en frío lo que ve."}, {"id": "opening.arranque_sin_disculpa", "weight": 0.2, "regla_id": "opening.gasman", "description": "Cero disculpas, cero peticiones de permiso, cero minimizarse durante TODA la sesion, incluso despues de una respuesta seca."}, {"id": "mindset.regla_10_por_ciento", "weight": 0.1, "regla_id": "opening.energia_verbal", "description": "Sostiene energia y postura frente a la sequedad del cliente. No se encoge, no baja el volumen, no empieza a despedirse."}, {"id": "opening.curiosidad_abierta", "weight": 0.15, "regla_id": "opening.curiosidad_abierta", "description": "Deja abierto quién es el vendedor: abre sin presentarse, es decir, sin decir en primera persona su propio nombre ni el de la empresa que representa. Si no se presentó, este criterio se cumple. Dirigirse al cliente por su nombre o con 'don', 'señor' o 'sir' NO es presentarse. Que el cliente termine preguntando quién es confirma que funcionó, pero que no lo pregunte no le quita nada. Presentarse de entrada no se penaliza: simplemente no acredita este criterio."}]}$g$::jsonb WHERE id = '1.6' AND practice_script->>'version' = '2.0.2';
UPDATE public.nodes SET practice_script = $g${"notes": "v2.0.0 El espejo ensena la doctrina completa: el bloqueo se endurece si lo peleas y se disuelve si lo aceptas. La consecuencia hace el trabajo, no el feedback.", "scope": {"skills_in_focus": ["blocks.air"], "out_of_scope_behavior": "redirect"}, "limits": {"max_turns": 5, "max_duration_seconds": 180, "min_turns_before_evaluation": 2}, "phases": {"i_do": {"briefing": "Me van a bloquear.\n\nCuenta los tres movimientos: acepto lo que me dijo sin discutirlo, no lo peleo ni lo justifico, y sigo con lo mio como si nada.\n\nFijate sobre todo en el tercero: no pido permiso otra vez, no pregunto si puedo seguir. Sigo.", "first_message": "Claro que si, entiendo. Oiga, y digame una cosa, cuanto tiempo lleva usted aqui?"}, "you_do": {"prompt": "REGLA NUMERO CERO, POR ENCIMA DE TODO LO DEMAS: en esta conversacion NO EXISTE el tema de que vende este senor, que trae, a que viene, ni en que te puede servir. Jamas preguntas eso. Ni con esas palabras ni con ninguna otra. Prohibidas de forma absoluta las frases: que se le ofrece, que necesita, que anda buscando, a que viene, que trae, de que se trata, en que le puedo servir, y cualquier variante. Tu no sabes que es vendedor y no te interesa averiguarlo. Si el menciona por su cuenta un producto o una marca, contestas ah orale y sigues con lo tuyo sin preguntar nada. Si te quedas sin saber que decir, hablas de tu propio negocio o del dia, nunca de el.\n\nEres el encargado de un negocio. En tu PRIMERA respuesta, sin importar lo que diga el vendedor, sueltas un bloqueo de reflejo: elige uno de estos y dilo con naturalidad, sin agresion, como quien despacha por costumbre — ahorita ando ocupado / no me interesa, gracias / no estoy comprando nada / ya tengo con quien. NO es personal, es un reflejo. DESPUES REACCIONAS ASI: si el vendedor DISCUTE, justifica o intenta convencerte de que si te interesa (es que solo son dos minutos, es que esto si le va a servir), tu bloqueo se endurece y se vuelve una posicion: ahora si te cierras de verdad y lo despachas. Si el vendedor SE DISCULPA o se va (perdon, con permiso, vengo despues), lo dejas ir sin insistir. Si el vendedor ACEPTA tu bloqueo sin pelearlo y sigue con su tema con naturalidad, tu tambien sigues con naturalidad: contestas su pregunta y la conversacion continua como si el bloqueo no hubiera existido. Asi funciona en la vida real: nadie defiende un reflejo si el otro no lo ataca. NUNCA vuelvas a bloquear despues del primero. Responde en 1 o 2 frases.", "objective": "El vendedor atraviesa el bloqueo con los tres movimientos: acepta, no lo pelea, y retoma su tema sin pedir permiso. El scope se cubre cuando la conversacion continua despues del bloqueo con el cliente participando con naturalidad."}, "closing": {"message": "Eso es atravesar un bloqueo. No lo peleaste, no te disculpaste y no te fuiste. Lo aceptaste y seguiste, y el bloqueo se disolvio solo, porque nunca fue una posicion: era un reflejo. Vamos al detalle.", "message_incomplete": "Ahi lo dejamos. Vamos al desglose y te digo como quedo ese bloqueo."}}, "version": "2.0.3", "i_do_type": "demo", "failure_criteria": [{"id": "discute_el_bloqueo", "regla_id": "blocks.discute_bloqueo", "severity": "critical", "description": "Intenta convencer al cliente de que si le interesa o de que si tiene tiempo. Convierte un reflejo en una posicion, y ahora si tiene un no de verdad enfrente."}, {"id": "se_disculpa_o_se_va", "regla_id": "blocks.se_rinde_al_bloqueo", "severity": "critical", "description": "Ante el bloqueo, se disculpa, se despide o promete volver despues. Se rindio ante un reflejo que no significaba nada. Si el cliente REPITE el bloqueo justo despues del AIR (dos no seguidos), quedar de regresar en otro momento es lo correcto y no es esta falla."}, {"id": "pide_permiso_de_nuevo", "regla_id": "blocks.air_sin_resume", "severity": "major", "description": "Acepta el bloqueo pero despues pide autorizacion para seguir. Le devuelve el control al cliente justo despues de haberlo recuperado."}, {"id": "ignora_sin_aceptar", "regla_id": "blocks.air_sin_aceptar", "severity": "minor", "description": "Sigue de largo sin reconocer lo que el cliente dijo. Se siente que no lo escucho, y eso enfria aunque tecnicamente avance.", "severity_override": {"razon": "incidental: fuera del foco del nodo", "default": "major"}}], "success_criteria": [{"id": "blocks.air", "weight": 1, "regla_id": "blocks.air", "description": "Los tres movimientos: ACEPTA el bloqueo con un entiendo, claro que si o por supuesto. NO lo discute, no lo justifica, no intenta convencer al cliente de lo contrario. RETOMA su tema con naturalidad y sin pedir permiso otra vez. El tercer movimiento es el que mas falla: muchos aceptan y despues se quedan esperando autorizacion."}]}$g$::jsonb WHERE id = '2.7' AND practice_script->>'version' = '2.0.2';
UPDATE public.nodes SET practice_script = $g${"notes": "v1.0.0 Dos no seguidos en la puerta (Emilio, 15-oct-2026). El primer bloqueo se pasa con AIR; el segundo, seguido, ya es un hoy no: se queda de regresar o se despide con amabilidad. El espejo ensena: si insiste, el cliente se cierra; si se va bien, queda la puerta abierta.", "scope": {"skills_in_focus": ["blocks.air", "blocks.dos_no_seguidos"], "out_of_scope_behavior": "redirect"}, "limits": {"max_turns": 5, "max_duration_seconds": 180, "min_turns_before_evaluation": 3}, "phases": {"i_do": {"briefing": "Me van a bloquear dos veces seguidas.\n\nAl primero le hago AIR: lo acepto, no lo discuto y sigo con lo mio.\n\nAl segundo ya no insisto: hoy no es el dia. Quedo de regresar, con dos opciones de dia, o me despido con amabilidad.", "first_message": "Claro, se ve que hoy esta a tope. Le queda mejor que pase el jueves o el viernes en la manana?"}, "you_do": {"prompt": "REGLA NUMERO CERO, POR ENCIMA DE TODO LO DEMAS: en esta conversacion NO EXISTE el tema de que vende este senor, que trae, a que viene, ni en que te puede servir. Jamas preguntas eso. Ni con esas palabras ni con ninguna otra. Prohibidas de forma absoluta las frases: que se le ofrece, que necesita, que anda buscando, a que viene, que trae, de que se trata, en que le puedo servir, y cualquier variante. Tu no sabes que es vendedor y no te interesa averiguarlo. Si el menciona por su cuenta un producto o una marca, contestas ah orale y sigues con lo tuyo sin preguntar nada. Si te quedas sin saber que decir, hablas de tu propio negocio o del dia, nunca de el.\n\nEres el encargado de un negocio y hoy de verdad andas a tope. En tu PRIMERA respuesta, sin importar lo que diga el vendedor, sueltas un bloqueo de reflejo, con naturalidad y sin agresion: ahorita ando ocupado / no me interesa, gracias / no estoy comprando nada. DESPUES REACCIONAS ASI: 1) Si el vendedor ACEPTA tu bloqueo sin pelearlo y sigue con su tema (hace AIR), en tu SEGUNDA respuesta repites el bloqueo de inmediato, mas firme pero amable, porque hoy de verdad no puedes: de verdad, ahorita no puedo, ando a tope. 2) Si despues de ese segundo bloqueo el vendedor queda de regresar otro dia o se despide con amabilidad, aceptas con gusto y te despides bien (si, el jueves esta bien, pasele), y ahi termina. 3) Si despues del segundo bloqueo el vendedor SIGUE insistiendo (nomas un minutito, dejeme le explico, vuelve a preguntar de su tema), te molestas: contestas seco y lo despachas. 4) Si el vendedor DISCUTE tu primer bloqueo o intenta convencerte de que si te interesa, te cierras de verdad y lo despachas. 5) Si el vendedor se disculpa o se va con el primer bloqueo, lo dejas ir sin insistir. NUNCA cambias de opinion despues del segundo bloqueo: hoy no puedes. Responde en 1 o 2 frases.", "objective": "El vendedor pasa el primer bloqueo con AIR y, ante el segundo bloqueo seguido, no insiste: queda de regresar en otro momento o se despide con amabilidad. El scope se cubre cuando el vendedor ya respondio al segundo bloqueo."}, "closing": {"message": "Eso es leer bien el momento. Pasaste el primer no con AIR, y al segundo no insististe: te fuiste bien y la puerta queda abierta para la siguiente visita. Vamos al detalle.", "message_incomplete": "Ahi lo dejamos. Vamos al desglose y te digo como quedaron esos dos no."}}, "version": "1.0.3", "i_do_type": "demo", "failure_criteria": [{"id": "insiste_tras_dos", "regla_id": "blocks.insistir_tras_dos_no", "severity": "critical", "description": "Despues del segundo bloqueo seguido sigue insistiendo: pide un minutito, vuelve a su tema o trata de convencerlo. Ya no es seguridad, es terquedad, y el cliente lo recibe cerrado la proxima vez. Solo cuenta lo que el vendedor dice DESPUES del segundo bloqueo: si todavia no ha contestado al segundo bloqueo, esta falla no aplica."}, {"id": "discute_el_bloqueo", "regla_id": "blocks.discute_bloqueo", "severity": "critical", "description": "Intenta convencer al cliente de que si le interesa o de que si tiene tiempo. Convierte un reflejo en una posicion, y ahora si tiene un no de verdad enfrente."}, {"id": "se_va_al_primero", "regla_id": "blocks.se_rinde_al_bloqueo", "severity": "critical", "description": "Ante el PRIMER bloqueo se disculpa, se despide o promete volver despues, sin intentar AIR. Se rindio ante un reflejo que no significaba nada. Quedar de regresar es correcto solo despues del segundo bloqueo seguido."}, {"id": "pide_permiso_de_nuevo", "regla_id": "blocks.air_sin_resume", "severity": "major", "description": "Acepta el primer bloqueo pero despues pide autorizacion para seguir. Le devuelve el control al cliente justo despues de haberlo recuperado."}, {"id": "se_va_con_disculpa", "regla_id": "opening.se_disculpa", "severity": "minor", "description": "Se despide despues del segundo bloqueo, pero pidiendo perdon por haberlo molestado (perdon por quitarle su tiempo, disculpe la molestia). Se hace menos: trae algo que le puede servir y no tiene por que disculparse.", "severity_override": {"razon": "incidental: fuera del foco del nodo", "default": "critical"}}], "success_criteria": [{"id": "blocks.air", "weight": 0.4, "regla_id": "blocks.air", "description": "Pasa el PRIMER bloqueo con los tres movimientos: lo ACEPTA con un entiendo, claro que si o por supuesto; NO lo discute ni se justifica; y RETOMA su tema con naturalidad, sin pedir permiso otra vez."}, {"id": "blocks.dos_no_seguidos", "weight": 0.6, "regla_id": "blocks.dos_no_seguidos", "description": "Ante el SEGUNDO bloqueo seguido, no insiste: queda de regresar en otro momento (mejor con dos opciones de dia, como jueves o viernes) o se despide con amabilidad. Cualquiera de las dos cumple. Si sigue insistiendo, no cumple. Si el vendedor se fue con el primer bloqueo, el cliente nunca repitio el bloqueo: este criterio es no_aplica, no cumple."}]}$g$::jsonb WHERE id = '2.7c' AND practice_script->>'version' = '1.0.2';
UPDATE public.nodes SET practice_script = $g${"notes": "v2.0.0 Nodo nuevo. Primera aparicion de Close With Action, en su version ligera: avanzar en la linea. Vuelve en M4 despues del precio y en M5 como cierre. El espejo castiga el silencio con la consecuencia real: el cliente se despide con amabilidad.", "scope": {"skills_in_focus": ["flow.close_with_action", "blocks.air"], "out_of_scope_behavior": "redirect"}, "limits": {"max_turns": 8, "max_duration_seconds": 210, "min_turns_before_evaluation": 3}, "phases": {"i_do": {"briefing": "Fijate en el momento justo despues de resolver algo. Ahi es donde el vendedor promedio se queda callado, esperando permiso para seguir.\n\nYo no. Resuelvo y avanzo en la misma frase, con la siguiente pregunta ya puesta.\n\nEl cliente nunca tiene que decidir si seguimos, porque ya seguimos.", "first_message": "Claro, entiendo perfecto. Y digame, cuanto tiempo lleva usted con el negocio?"}, "you_do": {"prompt": "REGLA NUMERO CERO, POR ENCIMA DE TODO LO DEMAS: en esta conversacion NO EXISTE el tema de que vende este senor, que trae, a que viene, ni en que te puede servir. Jamas preguntas eso. Ni con esas palabras ni con ninguna otra. Prohibidas de forma absoluta las frases: que se le ofrece, que necesita, que anda buscando, a que viene, que trae, de que se trata, en que le puedo servir, y cualquier variante. Tu no sabes que es vendedor y no te interesa averiguarlo. Si el menciona por su cuenta un producto o una marca, contestas ah orale y sigues con lo tuyo sin preguntar nada. Si te quedas sin saber que decir, hablas de tu propio negocio o del dia, nunca de el.\n\nEres el encargado de un negocio. Vas a poner pequenos frenos a lo largo de la conversacion: en tu primera respuesta un bloqueo suave (ando ocupado, no me interesa), y mas adelante uno o dos frenos menores (una duda corta, un ahorita no se, un uf pues no se). TU REGLA PRINCIPAL: despues de CADA freno tuyo, observas que hace el vendedor. Si el vendedor resuelve y SE QUEDA CALLADO, o pregunta si puede continuar, o espera tu reaccion, entonces TU TOMAS EL CONTROL: dices bueno pues ahi luego me dice, gracias eh, y empiezas a despedirte con amabilidad. La conversacion se te acaba en las manos. Si el vendedor resuelve y AVANZA de inmediato con otra pregunta o retomando su tema sin pedir permiso, tu sigues la conversacion con naturalidad y contestas lo que te pregunte. Nunca eres tu quien reactiva la conversacion despues de un silencio. Responde en 1 o 2 frases.", "objective": "El vendedor avanza por su cuenta despues de cada freno del cliente, sin quedarse esperando ni pedir permiso para continuar. El scope se cubre cuando la conversacion sobrevive al menos dos frenos porque el vendedor la movio las dos veces."}, "closing": {"message": "Eso es seguir avanzando. Cada vez que algo te freno, resolviste y seguiste tu, sin esperar a que el cliente decidiera. Esa es la diferencia entre una conversacion que avanza y una que se apaga en un silencio. Vamos al detalle.", "message_incomplete": "Ahi lo dejamos. Vamos al desglose y te digo donde se te fue el control."}}, "version": "2.0.1", "i_do_type": "demo", "failure_criteria": [{"id": "se_queda_esperando", "regla_id": "close.devuelve_el_volante", "severity": "critical", "description": "Resuelve el freno y se queda callado esperando la reaccion del cliente. En ese silencio el cliente retoma el control y la conversacion se acaba.", "severity_override": {"razon": "escalada: habilidad espejo del nodo", "default": "major"}}, {"id": "pide_autorizacion", "regla_id": "opening.pide_permiso", "severity": "critical", "description": "Pregunta si puede continuar, si le permite seguir o si tiene mas tiempo. Le entrega el control justo despues de haberlo recuperado."}, {"id": "avanza_atropellando", "regla_id": "blocks.air_sin_aceptar", "severity": "minor", "description": "Avanza sin reconocer lo que el cliente acaba de decir. Se siente que no lo escucho.", "severity_override": {"razon": "incidental: fuera del foco del nodo", "default": "major"}}, {"id": "pitch_prematuro", "regla_id": "opening.pitch_prematuro", "severity": "critical", "description": "Mete producto, promocion o motivo de venta."}], "success_criteria": [{"id": "flow.close_with_action", "weight": 0.7, "regla_id": "close_with_action", "description": "Despues de cada freno del cliente, el vendedor avanza por su cuenta: hace la siguiente pregunta o retoma su tema en la misma intervencion, sin pausas de espera y sin pedir autorizacion. No deja que el cliente decida si la conversacion continua."}, {"id": "blocks.air", "weight": 0.3, "regla_id": "blocks.air", "description": "Cada freno se acepta sin pelearlo antes de avanzar. Avanzar sin reconocer lo que el cliente dijo se siente atropellado."}]}$g$::jsonb WHERE id = '2.9' AND practice_script->>'version' = '2.0.0';
UPDATE public.nodes SET practice_script = $g${"notes": "v2.0.0 BOSS del Mundo 2. Sin pistas garantizadas (R9). Acumulativo: el Mundo 1 se examina implicitamente porque una apertura mal hecha no abre la conversacion. La senal de exito es que el cliente pregunte en que le puede servir, que es la puerta al Descubrimiento.", "scope": {"skills_in_focus": ["blocks.air", "story.historia_breve", "story.brevedad", "relationship.cpr", "flow.close_with_action", "story.relevancia_cliente"], "out_of_scope_behavior": "redirect"}, "limits": {"max_turns": 12, "max_duration_seconds": 300, "min_turns_before_evaluation": 4}, "phases": {"i_do": {"briefing": "Este es el examen del mundo. Bloqueo de entrada, historia breve, relacion personal y seguir avanzando: todo junto y con un cliente que no ayuda.\n\nSin pistas.", "first_message": "Entiendo perfecto, no se preocupe. Soy Emilio, ando trabajando con los negocios de esta zona y quise pasar a conocer el suyo.\n\nDigame una cosa, cuanto tiempo lleva usted aqui?"}, "you_do": {"prompt": "REGLA NUMERO CERO, POR ENCIMA DE TODO LO DEMAS: en esta conversacion NO EXISTE el tema de que vende este senor, que trae, a que viene, ni en que te puede servir. Jamas preguntas eso. Ni con esas palabras ni con ninguna otra. Prohibidas de forma absoluta las frases: que se le ofrece, que necesita, que anda buscando, a que viene, que trae, de que se trata, en que le puedo servir, y cualquier variante. Tu no sabes que es vendedor y no te interesa averiguarlo. Si el menciona por su cuenta un producto o una marca, contestas ah orale y sigues con lo tuyo sin preguntar nada. Si te quedas sin saber que decir, hablas de tu propio negocio o del dia, nunca de el.\n\nEres el encargado de un negocio, ocupado y con poca paciencia para vendedores. En tu PRIMERA respuesta sueltas un bloqueo de reflejo, con naturalidad y sin agresion: ahorita ando ocupado / no me interesa / no estoy comprando nada. TU COMPORTAMIENTO: eres cortes pero cerrado y contestas corto. NO ofreces informacion y NO llevas la conversacion. REGLAS DE REACCION: 1) Si el vendedor pelea el bloqueo, se disculpa o se va, lo despachas y la conversacion termina. 2) Si lo acepta y sigue, continuas con naturalidad. 3) Si su historia breve se alarga mas de tres o cuatro frases, te desconectas: contestas ajam y dices que andas ocupado. 4) Si el vendedor resuelve algo y se queda callado esperando, TU tomas el control y empiezas a despedirte con amabilidad. 5) En tu tercera o cuarta respuesta, si la conversacion sigue viva, sueltas de manera natural UN dato personal tuyo, al pasar, sin darle importancia: elige entre familia, como empezaste, que haces los domingos, por que pusiste el negocio, o tu equipo. Si el vendedor lo ignora, te enfrias y ya no ofreces nada mas de ti. Si le entra con interes real, te abres notablemente. Si se queda platicando de eso mas de dos intercambios sin volver al negocio, te acomodas a platicar de la vida y ya nunca regresas tu al tema. 6) SOLO si el vendedor logra todo — atravesar el bloqueo, decir quien es breve y relevante, conectar contigo como persona y regresar, y avanzar sin pedir permiso — entonces te abres de verdad: le cuentas algo de tu negocio por tu cuenta y le preguntas en que le puede servir. Esa pregunta es la senal de que gano. NUNCA la hagas antes de que se lo gane. Responde en 1 o 2 frases.", "objective": "El vendedor atraviesa el bloqueo inicial, se presenta en quince segundos de forma relevante, conecta con el dato personal y regresa, y sostiene el avance sin pedir permiso. El scope se cubre cuando el cliente se abre por su propia voluntad y pregunta en que le puede servir."}, "closing": {"message": "Ahi esta la puerta fria abierta. Atravesaste el bloqueo sin pelearlo, dijiste quien eras sin cansarlo, conectaste como persona y volviste, y nunca soltaste el control de la conversacion. Ese cliente ya quiere saber en que le puedes servir, y eso es exactamente lo que sigue. Vamos al detalle.", "message_incomplete": "Hasta aqui la sesion. Ya tengo lo que necesito para tu analisis. Vamos al desglose y te digo donde estuvo la diferencia."}}, "version": "2.1.2", "i_do_type": "demo", "failure_criteria": [{"id": "discute_el_bloqueo", "regla_id": "blocks.discute_bloqueo", "severity": "critical", "description": "Pelea el bloqueo inicial o intenta convencer al cliente de que si le interesa."}, {"id": "se_disculpa_o_se_va", "regla_id": "blocks.se_rinde_al_bloqueo", "severity": "critical", "description": "Ante el bloqueo, se disculpa, se despide o promete volver despues. Si el cliente REPITE el bloqueo justo despues del AIR (dos no seguidos), quedar de regresar en otro momento es lo correcto y no es esta falla."}, {"id": "se_queda_esperando", "regla_id": "close.devuelve_el_volante", "severity": "critical", "description": "Resuelve algo y se queda callado esperando permiso. El cliente toma el control y se despide.", "severity_override": {"razon": "boss: escalada", "default": "major"}}, {"id": "historia_larga", "regla_id": "story.kill", "severity": "major", "description": "La historia breve se extiende y el cliente se desconecta."}, {"id": "ignora_lo_personal", "regla_id": "story.nunca_sale", "severity": "major", "description": "Pasa de largo el dato personal que el cliente ofrecio.", "severity_override": {"razon": "boss: escalada", "default": "minor"}}, {"id": "se_queda_platicando", "regla_id": "story.sale_sin_regresar", "severity": "major", "description": "Le entra a lo personal y ya no vuelve al negocio."}, {"id": "pitch_prematuro", "regla_id": "opening.pitch_prematuro", "severity": "critical", "description": "Mete producto, promocion o motivo de venta. Identificarse con nombre y empresa es el trabajo de este paso, no una excepción: aquí SÍ se dice quién eres y por qué estás."}], "success_criteria": [{"id": "blocks.air", "weight": 0.25, "regla_id": "blocks.air", "description": "Atraviesa el bloqueo inicial: lo acepta, no lo pelea, y retoma sin pedir permiso."}, {"id": "story.historia_breve", "weight": 0.15, "regla_id": "story.quien_eres_por_que", "description": "Dice quien es y por que esta ahi: nombre, procedencia y motivo humano de la visita."}, {"id": "story.brevedad", "weight": 0.1, "regla_id": "story.kiss", "description": "Dos o tres frases. Sin trayectoria de empresa, sin lista de productos, sin cifras."}, {"id": "relationship.cpr", "weight": 0.2, "regla_id": "relationship.cpr", "description": "Detecta el dato personal, le entra con interes genuino, y REGRESA al negocio por su cuenta en uno o dos intercambios."}, {"id": "flow.close_with_action", "weight": 0.15, "regla_id": "close_with_action", "description": "Despues de cada freno avanza por su cuenta, sin quedarse esperando ni pedir autorizacion. Sostiene el control de la conversacion toda la sesion."}, {"id": "story.relevancia_cliente", "weight": 0.15, "regla_id": "story.pregunta_despues", "description": "Sus turnos terminan devolviéndole la palabra al cliente con una pregunta: no deja afirmaciones sueltas en el aire."}]}$g$::jsonb WHERE id = '2.10' AND practice_script->>'version' = '2.1.1';

-- 4. Chequeo final.
DO $chk$ BEGIN
  IF (SELECT md5(practice_script::text) FROM public.nodes WHERE id = '1.4') IS DISTINCT FROM 'b35fbc3bb883bba61506b22657c353c0' THEN RAISE EXCEPTION 'el guion del 1.4 no quedó'; END IF;
  IF (SELECT md5(practice_script::text) FROM public.nodes WHERE id = '1.6') IS DISTINCT FROM 'c5383d8d5e8ae94ac91a89792f2ac4c1' THEN RAISE EXCEPTION 'el guion del 1.6 no quedó'; END IF;
  IF (SELECT md5(practice_script::text) FROM public.nodes WHERE id = '2.7') IS DISTINCT FROM 'b868bebb7afeb790b675c8dbdfe995e2' THEN RAISE EXCEPTION 'el guion del 2.7 no quedó'; END IF;
  IF (SELECT md5(practice_script::text) FROM public.nodes WHERE id = '2.7c') IS DISTINCT FROM 'c3c4815ce1e4bd797567554401f1d6d0' THEN RAISE EXCEPTION 'el guion del 2.7c no quedó'; END IF;
  IF (SELECT md5(practice_script::text) FROM public.nodes WHERE id = '2.9') IS DISTINCT FROM '277c851eeb0c452ac2b4d9f98ba13fde' THEN RAISE EXCEPTION 'el guion del 2.9 no quedó'; END IF;
  IF (SELECT md5(practice_script::text) FROM public.nodes WHERE id = '2.10') IS DISTINCT FROM 'b84e28cf551e20177ed936e5a61e87b4' THEN RAISE EXCEPTION 'el guion del 2.10 no quedó'; END IF;
  IF (SELECT resumen FROM public.reglas WHERE id = 'opening.pide_permiso') IS DISTINCT FROM $v$Pedir autorización para hablar o para seguir: entrega el control y le ofrece al cliente una salida gratis. LA PRUEBA: ¿la frase le da al cliente la opción de decir que no a seguir la plática? Ejemplos que ilustran —no delimitan—: «¿tiene un minutito?», «¿me permite?», «¿le puedo preguntar algo?», «si no le molesta…». Si la frase no le da esa opción, no es pedir permiso, diga lo que diga.$v$ THEN RAISE EXCEPTION 'la regla opening.pide_permiso no quedó'; END IF;
  IF (SELECT resumen FROM public.reglas WHERE id = 'blocks.discute_bloqueo') IS DISTINCT FROM $v$Discutir un bloqueo lo convierte en posición y le crea al cliente un no que no tenía. LA PRUEBA: ¿el vendedor trata de cambiar el no del cliente: convencerlo de que sí le interesa, de que sí tiene tiempo o de que será rápido? Si acepta el no y sigue con su tema, no es discutir, diga lo que diga.$v$ THEN RAISE EXCEPTION 'la regla blocks.discute_bloqueo no quedó'; END IF;
  IF (SELECT resumen FROM public.reglas WHERE id = 'blocks.air_sin_resume') IS DISTINCT FROM $v$Aceptar el bloqueo pero no retomar. LA PRUEBA: después de aceptar, ¿el vendedor se queda callado esperando que el cliente le dé pie, o pide permiso para seguir (con la prueba de pedir permiso: una frase que le da al cliente la opción de decir que no a seguir)? Si sigue con su tema o con una pregunta, sí retomó.$v$ THEN RAISE EXCEPTION 'la regla blocks.air_sin_resume no quedó'; END IF;
  IF (SELECT resumen FROM public.reglas WHERE id = 'blocks.insistir_tras_dos_no') IS DISTINCT FROM $v$Seguir insistiendo después de dos no seguidos en la puerta: ya no es seguridad, es terquedad. LA PRUEBA: después del segundo no seguido, ¿el vendedor sigue con su tema (otra pregunta, una explicación, un «nomás un minutito») en vez de quedar de regresar o despedirse? Solo cuenta lo que dice después del segundo no.$v$ THEN RAISE EXCEPTION 'la regla blocks.insistir_tras_dos_no no quedó'; END IF;
  IF NOT EXISTS (SELECT 1 FROM public.reglas WHERE id = 'blocks.se_rinde_al_bloqueo' AND severidad_default = 'critical') THEN RAISE EXCEPTION 'falta la regla blocks.se_rinde_al_bloqueo'; END IF;
  IF NOT EXISTS (SELECT 1 FROM public.reglas WHERE id = 'blocks.air_sin_aceptar' AND severidad_default = 'major') THEN RAISE EXCEPTION 'falta la regla blocks.air_sin_aceptar'; END IF;
  IF NOT EXISTS (SELECT 1 FROM public.reglas WHERE id = 'opening.se_disculpa' AND severidad_default = 'critical') THEN RAISE EXCEPTION 'falta la regla opening.se_disculpa'; END IF;
END $chk$;
